import{_ as n,C as o,o as r,c as s,j as e,a as i,E as d,a2 as c}from"./chunks/framework.sc8Z_ZE3.js";const f=JSON.parse('{"title":"Jira","description":"","frontmatter":{},"headers":[],"relativePath":"connections/jira.md","filePath":"connections/jira.md"}'),l={name:"connections/jira.md"};function h(g,t,u,p,m,w){const a=o("Badge");return r(),s("div",null,[t[0]||(t[0]=e("h1",{id:"jira",tabindex:"-1"},[i("Jira "),e("a",{class:"header-anchor",href:"#jira","aria-label":'Permalink to "Jira"'},"​")],-1)),d(a,{type:"tried",text:"In real runs"}),t[1]||(t[1]=c(' Jira Cloud, Server and Data Center. Octryx AI reads tickets as work items and as knowledge; agents can read and, if allowed, write.<h2 id="set-it-up" tabindex="-1">Set it up <a class="header-anchor" href="#set-it-up" aria-label="Permalink to &quot;Set it up&quot;">​</a></h2><p><strong>Admin › Connections › Add connection</strong>, type <strong>Jira</strong>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Jira URL</strong></td><td>Cloud: the site root, <code>https://your-site.atlassian.net</code> (no <code>/jira</code>). Server and Data Center: the base URL.</td></tr><tr><td><strong>Authentication</strong></td><td>one of the sign-ins below</td></tr><tr><td><strong>Projects</strong></td><td>the project keys it may touch, for example <code>OCX, SHOP</code></td></tr></tbody></table><p>Sign-ins:</p><ul><li><strong>Cloud: email and API token</strong>: the account email and an API token from id.atlassian.com.</li><li><strong>User and password</strong>: Server and Data Center.</li><li><strong>Personal access token</strong>: Server and Data Center.</li><li><strong>OpenID Connect client credentials</strong>: token endpoint, client id and client secret, optionally scope, audience and client authentication.</li></ul><p><strong>Test</strong> calls Jira&#39;s &quot;myself&quot; endpoint and answers &quot;Connected to Jira (REST API 3)&quot; or names what is wrong.</p><h2 id="what-octryx-ai-does-with-it" tabindex="-1">What Octryx AI does with it <a class="header-anchor" href="#what-octryx-ai-does-with-it" aria-label="Permalink to &quot;What Octryx AI does with it&quot;">​</a></h2><ul><li><strong>Tickets</strong>: a JQL filter decides which tickets come in as work items, read on a schedule; a status mapping links Jira&#39;s statuses to Octryx AI&#39;s. Writing back status changes is part of the Workspace&#39;s work item workflow, not of the connection.</li><li><strong>Knowledge</strong>: each issue becomes a document titled with its key, so agents cite it. Issues with a security level are always withheld. See <a href="/docs/knowledge/guide#_3-connect-jira">Build your knowledge</a>.</li><li><strong>Agent tools</strong>, read: search tickets, read a ticket, users, projects, issue types, priorities, transitions, versions, boards and sprints.</li><li><strong>Agent tools</strong>, write (only with <strong>Read and write</strong>, and with the confirmation described in <a href="/docs/connections/#writes-need-a-person">Connections</a>): transition, comment, create and update tickets, create and release versions, create sprints and add issues to them.</li><li><strong>Workflows</strong> comment on the ticket, create a bug ticket and move it along, as the workflow defines.</li><li>Through Octryx AI&#39;s own <a href="/docs/connections/mcp#octryx-ai-as-an-mcp-server">MCP server</a>, Jira is read-only.</li></ul><p>Cloud and Server differ in their APIs (search, user ids, text format); Octryx AI handles both and remembers the API version per instance.</p>',10))])}const y=n(l,[["render",h]]);export{f as __pageData,y as default};
